  "inlineSchema": "datasource db {\n  provider = \"mongodb\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// 1. User (Owner Details)\nmodel User {\n  id        String    @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name      String\n  mobile    String    @unique\n  email     String    @unique\n  password  String\n  status    String    @default(\"ACTIVE\") // ACTIVE, INACTIVE, SUSPENDED\n  lastLogin DateTime? @map(\"last_login\")\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n\n  address         String?\n  companyName     String? @map(\"company_name\")\n  secondaryMobile String? @map(\"secondary_mobile\")\n  city            String? @map(\"city\")\n  education       String? @map(\"education\")\n\n  documents OwnerDocument[]\n\n  @@map(\"users\")\n}\n\n// 1b. Owner Documents Drive Vault\nmodel OwnerDocument {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId    String   @map(\"user_id\") @db.ObjectId\n  title     String\n  category  String // RC_BOOK, INSURANCE, PERMIT, ID_PROOF, TAX, CONTRACT, OTHER\n  fileUrl   String   @map(\"file_url\")\n  fileName  String   @map(\"file_name\")\n  fileSize  String?  @map(\"file_size\")\n  fileType  String?  @map(\"file_type\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@map(\"owner_documents\")\n}\n\n// 2. Class Machine Bills\nmodel ClassBill {\n  id            String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  date          DateTime @default(now())\n  place         String\n  customerName  String   @map(\"customer_name\")\n  contactNumber String   @map(\"contact_number\")\n  timeHours     Float    @map(\"time_hours\")\n  totalAmount   Float    @map(\"total_amount\")\n  advance       Float\n  balance       Float\n  remarks       String?\n  status        Int      @default(0) // 0 = PENDING, 1 = COMPLETED\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  payments ClassBillPayment[]\n\n  @@map(\"class_bills\")\n}\n\nmodel ClassBillPayment {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  billId      String   @map(\"bill_id\") @db.ObjectId\n  amount      Float\n  paymentDate DateTime @default(now()) @map(\"payment_date\")\n  remarks     String?\n\n  bill ClassBill @relation(fields: [billId], references: [id])\n\n  @@map(\"class_bill_payments\")\n}\n\n// 3. Kartar Machine Bills\nmodel KartarBill {\n  id            String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  date          DateTime @default(now())\n  place         String\n  customerName  String   @map(\"customer_name\")\n  contactNumber String   @map(\"contact_number\")\n  timeHours     Float    @map(\"time_hours\")\n  totalAmount   Float    @map(\"total_amount\")\n  advance       Float\n  balance       Float\n  remarks       String?\n  status        Int      @default(0) // 0 = PENDING, 1 = COMPLETED\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  payments KartarBillPayment[]\n\n  @@map(\"kartar_bills\")\n}\n\nmodel KartarBillPayment {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  billId      String   @map(\"bill_id\") @db.ObjectId\n  amount      Float\n  paymentDate DateTime @default(now()) @map(\"payment_date\")\n  remarks     String?\n\n  bill KartarBill @relation(fields: [billId], references: [id])\n\n  @@map(\"kartar_bill_payments\")\n}\n\n// 5. Operator Records Module\nmodel Operator {\n  id           String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  operatorName String   @map(\"operator_name\")\n  mobile       String\n  salary       Float\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  attendances OperatorAttendance[]\n  payments    OperatorSalaryPayment[]\n\n  @@map(\"operators\")\n}\n\nmodel OperatorAttendance {\n  id         String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  operatorId String   @map(\"operator_id\") @db.ObjectId\n  date       DateTime @default(now())\n  status     String // PRESENT, ABSENT\n  dailyWage  Float?   @map(\"daily_wage\")\n\n  operator Operator @relation(fields: [operatorId], references: [id])\n\n  @@map(\"operator_attendances\")\n}\n\nmodel OperatorSalaryPayment {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  operatorId  String   @map(\"operator_id\") @db.ObjectId\n  amount      Float\n  paymentDate DateTime @default(now()) @map(\"payment_date\")\n  remarks     String?\n\n  operator Operator @relation(fields: [operatorId], references: [id])\n\n  @@map(\"operator_salary_payments\")\n}\n\n// 6. Bunk Details Module\nmodel BunkDetail {\n  id            String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  date          DateTime @default(now())\n  fuelAmount    Float    @map(\"fuel_amount\")\n  paidAmount    Float    @default(0) @map(\"paid_amount\")\n  balance       Float    @default(0) @map(\"balance\")\n  paymentStatus String   @default(\"PAID\") @map(\"payment_status\") // PAID, PENDING\n  purchasesJson String?  @map(\"purchases_json\") // JSON array of itemized purchases\n  paymentsJson  String?  @map(\"payments_json\") // JSON array of itemized payments\n  remarks       String?\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"bunk_details\")\n}\n",
